    [47] = {
      beijing = 1674,
      dialog = 3,
      music = "305_ZQL_Second",
      renwu = "npc",
      sentence = "The spot-on guess sent me squirming under the covers, but he was a step faster and held my head to his chest, letting out a laugh.",
