    [61] = {
      beijing = 1674,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "As I said that, something else occurred to me: I poked at the drum kit and the electric guitar on the ground behind \"him\" in the video.",
